package cl.bolsillo.app;
import org.json.*;import java.net.*;import java.util.*;
public class PublicReleaseTest {
 static int count;static void yes(boolean condition,String label){count++;if(!condition)throw new AssertionError(label);}interface Work{void run()throws Exception;}static void rejects(Work test,String name)throws Exception{boolean failed=false;try{test.run();}catch(Exception e){failed=true;}yes(failed,name);}
 static JSONObject release()throws Exception{return new JSONObject().put("tag_name","v16.0").put("html_url","https://github.com/MatPR-26/Bolsillo/releases/tag/v16.0").put("body","Mejoras").put("assets",new JSONArray().put(new JSONObject().put("name","Bolsillo-16.apk").put("size",500000).put("digest","sha256:"+String.join("",Collections.nCopies(64,"a"))).put("browser_download_url","https://github.com/MatPR-26/Bolsillo/releases/download/v16.0/Bolsillo-16.apk")));}
 public static void main(String[] args)throws Exception{
  JSONObject series=Ledger.initial();series.getJSONArray("accounts").put(Ledger.account("credit-test","Crédito","credit","other"));Ledger.find(series.getJSONArray("accounts"),"cash").put("included",false);java.time.LocalDate first=java.time.LocalDate.of(2026,2,1);for(int i=0;i<60;i++){String kind=i%3==0?"income":i%3==1?"expense":"transfer",account=i%4==0?"credit-test":i%4==1?"cash":"bank-mach";JSONObject tx=NativeSync.transaction(kind,1000+i,account,kind.equals("transfer")?"bank-bancoestado":"",kind.equals("income")?"income-0":kind.equals("expense")?"expense-0":"","Serie","manual","");tx.put("date",first.minusDays(5).plusDays(i).toString());if(i%7==0)tx.put("status","pending");if(account.equals("credit-test"))tx.put("installments",3);series.getJSONArray("transactions").put(tx);}Ledger.validate(series);long[] daily=Ledger.dailyTotals(series,first,28);for(int day=0;day<28;day++){Map<String,Long> balances=Ledger.balances(series,first.plusDays(day).toString());long exact=0;for(int i=0;i<series.getJSONArray("accounts").length();i++){JSONObject account=series.getJSONArray("accounts").getJSONObject(i);if(account.optBoolean("included"))exact+=balances.get(account.getString("id"));}yes(daily[day]==exact,"daily chart retains exact balance on day "+day);}yes(Ledger.dailyTotals(series,first,0).length==0,"empty daily series");
  String repo="MatPR-26/Bolsillo";ReleaseFeed.Release latest=ReleaseFeed.parse(repo,release());yes(latest.code==16&&latest.version.equals("v16.0")&&latest.bytes==500000,"stable version and exact asset");yes(ReleaseFeed.cached(latest.json()).sha256.equals(latest.sha256),"metadata cache round trip");
  rejects(()->ReleaseFeed.parse(repo,release().put("draft",true)),"draft not offered");rejects(()->ReleaseFeed.parse(repo,release().put("prerelease",true)),"beta not offered");rejects(()->ReleaseFeed.parse(repo,release().put("tag_name","v16-beta")),"ambiguous version rejected");rejects(()->ReleaseFeed.parse(repo,release().put("tag_name","v99999999999")),"overflow version rejected");rejects(()->ReleaseFeed.parse(repo,release().put("html_url","https://github.com/other/repo/releases/tag/v16.0")),"foreign repository rejected");
  for(String field:new String[]{"digest","browser_download_url","size"}){JSONObject bad=release();bad.getJSONArray("assets").getJSONObject(0).remove(field);rejects(()->ReleaseFeed.parse(repo,bad),"missing "+field+" rejected");}
  JSONObject huge=release();huge.getJSONArray("assets").getJSONObject(0).put("size",ReleaseFeed.MAX_APK+1);rejects(()->ReleaseFeed.parse(repo,huge),"oversized download rejected");JSONObject insecure=release();insecure.getJSONArray("assets").getJSONObject(0).put("browser_download_url","http://github.com/MatPR-26/Bolsillo/releases/download/v16.0/Bolsillo-16.apk");rejects(()->ReleaseFeed.parse(repo,insecure),"http download rejected");JSONObject duplicated=release();duplicated.getJSONArray("assets").put(duplicated.getJSONArray("assets").getJSONObject(0));rejects(()->ReleaseFeed.parse(repo,duplicated),"duplicate asset rejected");
  for(String url:new String[]{"https://github.com.evil.example/a","https://evil.example/a","https://github.com:8443/a","https://user:pass@github.com/a","http://release-assets.githubusercontent.com/a","file:///tmp/a"})yes(!ReleaseFeed.downloadHost(new URL(url)),"host boundary "+url);yes(ReleaseFeed.downloadHost(new URL("https://release-assets.githubusercontent.com/a")),"official redirected asset host allowed");yes(!ReleaseFeed.repository("a/../b")&&!ReleaseFeed.repository("https://github.com/a/b")&&ReleaseFeed.repository(repo),"repository strictly bounded");
  JSONObject data=Ledger.initial();JSONObject person=new JSONObject().put("id","family").put("name","Familia");data.getJSONArray("people").put(person);JSONObject expense=NativeSync.transaction("expense",9990,"bank-mach","","expense-7","Netflix","manual","").put("id","netflix").put("shares",new JSONArray().put(new JSONObject().put("id","share").put("personId","family").put("name","Familia").put("amount",5000)));data.getJSONArray("transactions").put(expense);Ledger.validate(data);String month=Ledger.today().substring(0,7);yes(Ledger.flow(data,month,"expense","")==4990,"monthly expense is my actual share");yes(Ledger.balances(data,Ledger.today()).get("bank-mach")==-9990,"bank debit remains full merchant charge");yes(Finance.owed(data,"expense",person)==5000,"advanced part is still owed");yes(SpendingCharts.slices(data,0).get(0).value==4990,"donut matches personal spending");
  String key="netflix:share";JSONObject income=NativeSync.transaction("income",2000,"bank-mach","","income-3","Primer pago","manual","");data.getJSONArray("transactions").put(income);Finance.linkIncome(data,income.getString("id"),key);Ledger.validate(data);yes(Ledger.flow(data,month,"expense","")==4990&&Ledger.flow(data,month,"income","")==0,"partial payment does not inflate income or change my share");yes(Finance.owed(data,"expense",person)==3000&&Ledger.balances(data,Ledger.today()).get("bank-mach")==-7990,"partial payment credited once and recorded");JSONObject finalIncome=NativeSync.transaction("income",3000,"bank-mach","","income-3","Último pago","manual","");data.getJSONArray("transactions").put(finalIncome);Finance.linkIncome(data,finalIncome.getString("id"),key);yes(Ledger.flow(data,month,"expense","")==4990&&Ledger.balances(data,Ledger.today()).get("bank-mach")==-4990,"settled shared bill reflects own expense and real balance");yes(Finance.owed(data,"expense",person)==0,"all installments settle claim");
  rejects(()->PersonRecords.remove(data,"family"),"linked person cannot be deleted with claims");String txs=data.getJSONArray("transactions").toString();PersonRecords.archive(data,"family");yes(person.optBoolean("archived")&&txs.equals(data.getJSONArray("transactions").toString()),"archiving preserves exact financial history");data.getJSONArray("people").put(new JSONObject().put("id","mistake").put("name","Error"));PersonRecords.remove(data,"mistake");yes(Ledger.find(data.getJSONArray("people"),"mistake")==null&&txs.equals(data.getJSONArray("transactions").toString()),"unused profile deleted without money changes");
  JSONArray sort=new JSONArray().put(new JSONObject().put("id","a").put("name","Ana").put("amount",100).put("date","2026-01-01")).put(new JSONObject().put("id","b").put("name","Bea").put("amount",300).put("date","2026-03-01"));yes(PersonRecords.sorted(sort,"date",Collections.emptyMap(),Collections.emptyMap()).get(0).getString("id").equals("b"),"date descending");yes(PersonRecords.sorted(sort,"amount",Collections.emptyMap(),Collections.emptyMap()).get(0).getString("id").equals("b"),"amount descending");yes(PersonRecords.sorted(sort,"name",Collections.emptyMap(),Collections.emptyMap()).get(0).getString("id").equals("a"),"name ascending");
  JSONObject fresh=BankCatalog.initial();yes(fresh.getJSONArray("accounts").length()==1&&fresh.getJSONArray("accounts").getJSONObject(0).getString("type").equals("cash"),"fresh public install starts without personal bank presets");BankCatalog.add(fresh,Arrays.asList("santander","falabella","mach"));yes(fresh.getJSONArray("accounts").length()==4&&!fresh.optBoolean("bankSetupPending"),"only selected banks are added");String selected=fresh.getJSONArray("accounts").toString();BankCatalog.add(fresh,Arrays.asList("santander","mach"));yes(selected.equals(fresh.getJSONArray("accounts").toString()),"template re-selection never duplicates or alters account balances");yes(Ledger.find(fresh.getJSONArray("accounts"),"bank-bancoestado")==null,"unused banks remain hidden");yes(BankCatalog.detect("Banco Santander Chile").equals("santander")&&BankCatalog.detect("com.bci.mobile").equals("bci"),"additional bank app labels recognized");yes(NotificationRouting.resolve(fresh.getJSONArray("accounts"),new JSONObject().put("kind","santander"),"",new JSONObject()).equals("bank-santander"),"bank notification without card uses its unique usable account");JSONObject second=Ledger.account("second-santander","Otra cuenta","bank","santander");fresh.getJSONArray("accounts").put(second);yes(NotificationRouting.resolve(fresh.getJSONArray("accounts"),new JSONObject().put("kind","santander"),"",new JSONObject()).isEmpty(),"multiple accounts require explicit choice");yes(NotificationRouting.resolve(fresh.getJSONArray("accounts"),new JSONObject().put("kind","wallet"),"",new JSONObject()).isEmpty(),"Wallet never guesses a bank");
  expense.getJSONArray("shares").getJSONObject(0).put("amount",9990);yes(Ledger.flow(data,month,"expense","")==0&&SpendingCharts.slices(data,0).isEmpty(),"fully advanced expense is not my consumption");System.out.println("PASS: "+count+" public release validation, shared expense accounting and person history checks");
 }
}
